od" value="<?= $value ?>" <?= $period===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach;?></div></fieldset><fieldset><legend>Ordenar</legend><div><?php foreach(['newest'=>'Mais recentes','oldest'=>'Mais antigas','name'=>'Nome','largest'=>'Maiores'] as $value=>$label):?><label><input type="radio" name="sort" value="<?= $value ?>" <?= $sort===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach;?></div></fieldset><fieldset class="studio-custom-period"><legend>Período específico</legend><p>Ao preencher as datas, o intervalo personalizado substitui o período rápido.</p><div class="studio-date-range"><label>Data inicial<input type="date" name="date_from" value="<?= htmlspecialchars((string)($_GET['date_from']??'')) ?>"></label><i>até</i><label>Data final<input type="date" name="date_to" value="<?= htmlspecialchars((string)($_GET['date_to']??'')) ?>"></label></div></fieldset><footer><a class="studio-btn" href="<?= url('/operation/media') ?>">Limpar</a><button class="studio-btn primary" type="submit"><ion-icon name="filter-outline"></ion-icon>Aplicar filtros</button></footer></form></aside></div>

