<?php $this->start('scripts') ?><script>
const mediaFilterDrawer=document.querySelector('[data-media-filter-drawer]');const mediaFilterToggle=open=>{mediaFilterDrawer?.classList.toggle('open',open);mediaFilterDrawer?.setAttribute('aria-hidden',open?'false':'true');document.body.classList.toggle('studio-filter-open',open)};document.querySelector('[data-media-filter-open]')?.addEventListener('click',()=>mediaFilterToggle(true));mediaFilterDrawer?.querySelectorAll('[data-media-filter-close]').forEach(button=>button.addEventListener('click',()=>mediaFilterToggle(false)));mediaFilterDrawer?.querySelectorAll('input[type="date"]').forEach(input=>input.addEventListener('click',()=>{if(typeof input.showPicker==='function')input.showPicker()}));
const mediaChecks=[...document.querySelectorAll('[data-media-select]')],mediaAll=document.querySelector('[data-media-select-all]'),mediaDelete=document.querySelector('[data-media-delete-selected]'),mediaCount=document.querySelector('[data-media-selected-count]');const mediaSelectionUpdate=()=>{const count=mediaChecks.filter(input=>input.checked).length;if(mediaCount)mediaCount.textContent=count+' selecionada'+(count===1?'':'s');if(mediaDelete)mediaDelete.disabled=count===0;if(mediaAll){mediaAll.checked=count>0&&count===mediaChecks.length;mediaAll.indeterminate=count>0&&count<mediaChecks.length}mediaChecks.forEach(input=>input.closest('article')?.classList.toggle('selected',input.checked))};mediaChecks.forEach(input=>input.addEventListener('change',mediaSelectionUpdate));mediaAll?.addEventListener('change',()=>{mediaChecks.forEach(input=>input.checked=mediaAll.checked);mediaSelectionUpdate()});document.querySelector('[data-media-selection-form]')?.addEventListener('submit',event=>{if(!confirm('Remover as imagens selecionadas que não estejam em uso?'))event.preventDefault()});
</script><?php $this->stop() ?>
